mapper.select:
SELECT u.id,COALESCE(NULLIF(u.real_name,''),u.username) name,COALESCE(t.team_name,'未分配团队') team_name FROM sys_user u LEFT JOIN sys_team t ON t.id=u.team_id
WHERE u.role_code IN ('SPECIALIST','MANAGER') OR EXISTS(SELECT 1 FROM crm_contract k WHERE k.performance_owner_id=u.id)u.team_id=#{s.teamId} OR EXISTS(SELECT 1 FROM crm_contract k WHERE k.performance_owner_id=u.id AND k.performance_team_id=#{s.teamId}) OR EXISTS(SELECT 1 FROM crm_payment_record r WHERE r.performance_owner_id=u.id AND r.performance_team_id=#{s.teamId})u.id=#{s.userId}
ORDER BY u.id

SELECT e.ownerId,COALESCE(NULLIF(u.real_name,''),u.username,'历史账号') ownerName,COALESCE(t.team_name,'未分配团队') teamName,
SUM(e.signedCount) signedCount,SUM(e.signedAmount) signedAmount,SUM(e.receivedAmount) receivedAmount,SUM(e.wonCount) wonCount,MAX(e.teamId) teamId FROM (
  SELECT k.performance_owner_id ownerId,k.performance_team_id teamId,COUNT(*) signedCount,SUM(k.performance_amount) signedAmount,0 receivedAmount,0 wonCount FROM crm_contract k WHERE  GROUP BY k.performance_owner_id,k.performance_team_id
  UNION ALL SELECT r.performance_owner_id ownerId,r.performance_team_id teamId,0 signedCount,0 signedAmount,SUM(r.received_amount) receivedAmount,0 wonCount FROM crm_payment_record r WHERE  GROUP BY r.performance_owner_id,r.performance_team_id
  UNION ALL SELECT k.performance_owner_id ownerId,k.performance_team_id teamId,0 signedCount,0 signedAmount,0 receivedAmount,COUNT(DISTINCT k.opportunity_id) wonCount FROM crm_contract k
  WHERE k.performance_confirmed_at IS NOT NULL AND 
  AND (SELECT MIN(l.occurred_at) FROM crm_opportunity_stage_log l WHERE l.opportunity_id=k.opportunity_id AND l.to_stage='WON') >= #{start}
  AND (SELECT MIN(l.occurred_at) FROM crm_opportunity_stage_log l WHERE l.opportunity_id=k.opportunity_id AND l.to_stage='WON') < #{end}
  GROUP BY k.performance_owner_id,k.performance_team_id
) e LEFT JOIN sys_user u ON u.id=e.ownerId LEFT JOIN sys_team t ON t.id=e.teamId GROUP BY e.ownerId,e.teamId,u.real_name,u.username,t.team_name ORDER BY signedAmount DESC,receivedAmount DESC,ownerId

SELECT COUNT(*) cohortCount,COALESCE(SUM(x.dealAt IS NOT NULL),0) dealCount,COALESCE(SUM(x.wonAt IS NOT NULL AND x.dealAt IS NOT NULL),0) wonCount,
AVG(CASE WHEN x.wonAt >= x.dealAt THEN TIMESTAMPDIFF(SECOND,x.dealAt,x.wonAt)/86400.0 END) averageSigningDays FROM (
  SELECT o.id,(SELECT MIN(l.occurred_at) FROM crm_opportunity_stage_log l WHERE l.opportunity_id=o.id AND l.to_stage='DEAL' AND l.occurred_at < #{end}) dealAt,
  (SELECT MIN(l.occurred_at) FROM crm_opportunity_stage_log l WHERE l.opportunity_id=o.id AND l.to_stage='WON' AND l.occurred_at < #{end}) wonAt
  FROM crm_opportunity o JOIN crm_customer c ON c.id=o.customer_id WHERE  AND o.created_at >= #{start} AND o.created_at < #{end}
) x
